using System.Security.Claims;
using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using SaaSPlatform.Api.BuildingBlocks.Application;
using SaaSPlatform.Api.BuildingBlocks.Infrastructure;
using SaaSPlatform.Api.Modules.Analytics.Application;
using SaaSPlatform.Api.Modules.Identity.Application;
using SaaSPlatform.Api.Modules.Identity.Domain;
using SaaSPlatform.Api.Modules.Inventory.Application;
using SaaSPlatform.Api.Modules.Inventory.Domain;
using SaaSPlatform.Api.Modules.Locations.Domain;
using SaaSPlatform.Api.Modules.Procurement.Application;
using SaaSPlatform.Api.Modules.Procurement.Domain;
using SaaSPlatform.Api.Modules.Tenancy.Application;
using SaaSPlatform.Api.Modules.Tenancy.Domain;

namespace SaaSPlatform.Api.Tests.Procurement;

#pragma warning disable CA1822

public sealed class ProcurementServiceTests
{
    [Fact] public async Task SupplierCodeIsTenantUniqueAndStatusIsControlled() { await using var f = await Fixture.Create(); var supplier = await f.Supplier(); await Assert.ThrowsAsync<ConflictException>(() => f.Procurement.CreateSupplier(f.User(), f.SupplierInput(), default)); var inactive = await f.Procurement.SetSupplierStatus(f.User(), supplier.Id, new(false, supplier.Version), default); Assert.Equal(SupplierStatus.Inactive, inactive.Status); }
    [Fact] public async Task SupplierPartLinksExistingInventoryPart() { await using var f = await Fixture.Create(); var supplier = await f.Supplier(); var part = await f.Part(); var link = await f.Procurement.UpsertSupplierPart(f.User(), supplier.Id, new(part.Id, "SUP-1", 12.5m, "SAR", 5, 7, true, Guid.Empty), default); Assert.Equal(part.Id, link.PartId); Assert.True(link.IsPreferred); }
    [Fact] public async Task TenantFilterHidesForeignSuppliers() { var store = Guid.NewGuid().ToString(); var a = Guid.NewGuid(); var b = Guid.NewGuid(); await using (var foreign = Fixture.CreateDatabase(new Current(b), store)) { foreign.Suppliers.Add(new Supplier { Id = Guid.NewGuid(), TenantId = b, Code = "FOREIGN", NameEn = "Foreign", DefaultCurrency = "SAR" }); await foreign.SaveChangesAsync(); } await using var current = Fixture.CreateDatabase(new Current(a), store); Assert.Empty(await current.Suppliers.ToListAsync()); }
    [Fact] public async Task SiteScopeRejectsForeignRequisition() { await using var f = await Fixture.Create(); var warehouse = await f.Warehouse(); var part = await f.Part(); await Assert.ThrowsAsync<UnauthorizedAccessException>(() => f.Procurement.CreateRequisition(f.User((TenantPermissions.ProcurementRequisitionsCreate, f.OtherSite.Id)), f.RequisitionInput(warehouse.Id, part.Id), default)); }

    [Fact] public async Task RequisitionDraftSupportsMultipleLinesAndSubmission() { await using var f = await Fixture.Create(); var warehouse = await f.Warehouse(); var a = await f.Part("PART-A"); var b = await f.Part("PART-B"); var input = f.RequisitionInput(warehouse.Id, a.Id) with { Lines = [new(a.Id, 10, null, 4, null), new(b.Id, 5, null, 8, null)] }; var request = await f.Procurement.CreateRequisition(f.User(), input, default); Assert.Equal(2, request.Lines.Count); request = await f.Procurement.SubmitRequisition(f.User(), request.Id, new(request.Version, "Ready"), default); Assert.Equal(PurchaseRequisitionStatus.Submitted, request.Status); }
    [Fact] public async Task RequesterCannotReviewOwnRequisition() { await using var f = await Fixture.Create(); var request = await f.SubmittedRequisition(); await Assert.ThrowsAsync<ConflictException>(() => f.Procurement.ReviewRequisition(f.User(), request.Id, new(request.Version, true, "Approve"), default)); }
    [Fact] public async Task ReviewerCanApproveOrRejectSubmittedRequisition() { await using var f = await Fixture.Create(); var request = await f.SubmittedRequisition(); var approved = await f.Procurement.ReviewRequisition(f.Reviewer(), request.Id, new(request.Version, true, "Budget approved"), default); Assert.Equal(PurchaseRequisitionStatus.Approved, approved.Status); Assert.Equal(f.ReviewerUser.Id, approved.ReviewedById); }
    [Fact] public async Task InvalidRequisitionTransitionIsRejected() { await using var f = await Fixture.Create(); var warehouse = await f.Warehouse(); var part = await f.Part(); var request = await f.Procurement.CreateRequisition(f.User(), f.RequisitionInput(warehouse.Id, part.Id), default); await Assert.ThrowsAsync<ConflictException>(() => f.Procurement.ReviewRequisition(f.Reviewer(), request.Id, new(request.Version, true, "Approve"), default)); }

    [Fact] public async Task ApprovedLineSupportsSplitConversionAcrossSuppliers() { await using var f = await Fixture.Create(); var request = await f.ApprovedRequisition(100); var s1 = await f.Supplier("SUP-1"); var s2 = await f.Supplier("SUP-2"); var first = await f.Procurement.CreatePurchaseOrder(f.User(), f.OrderInput(request, s1.Id, 60, 10), default); var refreshed = await f.Procurement.Requisition(f.User(), request.Id, default); Assert.Equal(PurchaseRequisitionStatus.PartiallyConverted, refreshed.Status); await f.Procurement.CreatePurchaseOrder(f.User(), f.OrderInput(refreshed, s2.Id, 40, 11), default); refreshed = await f.Procurement.Requisition(f.User(), request.Id, default); Assert.Equal(PurchaseRequisitionStatus.Converted, refreshed.Status); Assert.Equal(100, refreshed.Lines.Single().ConvertedQuantity); Assert.NotEqual(first.Number, (await f.Database.PurchaseOrders.OrderBy(x => x.Number).LastAsync()).Number); }
    [Fact] public async Task OverConversionIsRejected() { await using var f = await Fixture.Create(); var request = await f.ApprovedRequisition(10); var supplier = await f.Supplier(); await Assert.ThrowsAsync<ConflictException>(() => f.Procurement.CreatePurchaseOrder(f.User(), f.OrderInput(request, supplier.Id, 11, 5), default)); }
    [Fact] public async Task PurchaseOrderTotalsAreCalculatedByServer() { await using var f = await Fixture.Create(); var request = await f.ApprovedRequisition(3); var supplier = await f.Supplier(); var order = await f.Procurement.CreatePurchaseOrder(f.User(), f.OrderInput(request, supplier.Id, 3, 12.34567m), default); Assert.Equal(37.04m, order.Subtotal); Assert.Equal(12.3457m, order.Lines.Single().UnitPrice); }

    [Fact] public async Task PartialAndFinalReceiptsUpdatePoAndInventoryValuation() { await using var f = await Fixture.Create(); var order = await f.IssuedOrder(10, 20); var location = await f.Location(order.DestinationWarehouseId); var first = await f.Procurement.ReceivePurchaseOrder(f.User(), order.Id, f.Receipt(order, location.Id, 4, 20), default); Assert.Equal(80, first.TotalCost); order = await f.Procurement.PurchaseOrder(f.User(), order.Id, default); Assert.Equal(PurchaseOrderStatus.PartiallyReceived, order.Status); var second = await f.Procurement.ReceivePurchaseOrder(f.User(), order.Id, f.Receipt(order, location.Id, 6, 30), default); order = await f.Procurement.PurchaseOrder(f.User(), order.Id, default); var balance = await f.Database.InventoryBalances.SingleAsync(); Assert.Equal(PurchaseOrderStatus.FullyReceived, order.Status); Assert.Equal(10, balance.QuantityOnHand); Assert.Equal(26, balance.AverageUnitCost); Assert.Equal(2, await f.Database.InventoryMovements.CountAsync(x => x.Type == InventoryMovementType.Receipt)); Assert.Equal(2, await f.Database.PurchaseReceipts.CountAsync()); }
    [Fact] public async Task ReceiptRetryIsIdempotent() { await using var f = await Fixture.Create(); var order = await f.IssuedOrder(5, 10); var location = await f.Location(order.DestinationWarehouseId); var input = f.Receipt(order, location.Id, 5, 10); var first = await f.Procurement.ReceivePurchaseOrder(f.User(), order.Id, input, default); var second = await f.Procurement.ReceivePurchaseOrder(f.User(), order.Id, input, default); Assert.Equal(first.Id, second.Id); Assert.Equal(5, (await f.Database.InventoryBalances.SingleAsync()).QuantityOnHand); Assert.Single(await f.Database.StockReceipts.ToListAsync()); }
    [Fact] public async Task OverReceiptIsRejectedWithoutChangingStock() { await using var f = await Fixture.Create(); var order = await f.IssuedOrder(5, 10); var location = await f.Location(order.DestinationWarehouseId); await Assert.ThrowsAsync<ConflictException>(() => f.Procurement.ReceivePurchaseOrder(f.User(), order.Id, f.Receipt(order, location.Id, 6, 10), default)); Assert.Empty(await f.Database.InventoryBalances.ToListAsync()); }
    [Fact] public async Task StalePurchaseOrderVersionIsRejected() { await using var f = await Fixture.Create(); var order = await f.IssuedOrder(5, 10); var location = await f.Location(order.DestinationWarehouseId); var input = f.Receipt(order, location.Id, 1, 10) with { PurchaseOrderVersion = Guid.NewGuid() }; await Assert.ThrowsAsync<ConflictException>(() => f.Procurement.ReceivePurchaseOrder(f.User(), order.Id, input, default)); }
    [Fact] public async Task ProcurementSchemaHasConcurrencyAndIdempotencyGuards() { await using var f = await Fixture.Create(); var order = f.Database.Model.FindEntityType(typeof(PurchaseOrder)); var receipt = f.Database.Model.FindEntityType(typeof(PurchaseReceipt)); Assert.True(order!.FindProperty(nameof(PurchaseOrder.Version))!.IsConcurrencyToken); Assert.Contains(receipt!.GetIndexes(), x => x.IsUnique && x.Properties.Select(p => p.Name).SequenceEqual([nameof(PurchaseReceipt.TenantId), nameof(PurchaseReceipt.RequestId)])); }

    private sealed class Fixture : IAsyncDisposable
    {
        private readonly ServiceProvider provider; public PlatformDbContext Database { get; } public ProcurementService Procurement { get; } public InventoryService Inventory { get; } public Guid TenantId { get; } public Site Site { get; } public Site OtherSite { get; } public PlatformUser UserEntity { get; } public PlatformUser ReviewerUser { get; }
        private Fixture(ServiceProvider provider, PlatformDbContext db, ProcurementService procurement, InventoryService inventory, Guid tenant, Site site, Site other, PlatformUser user, PlatformUser reviewer) { this.provider = provider; Database = db; Procurement = procurement; Inventory = inventory; TenantId = tenant; Site = site; OtherSite = other; UserEntity = user; ReviewerUser = reviewer; }
        public static async Task<Fixture> Create() { var tenantId = Guid.NewGuid(); var current = new Current(tenantId); var services = new ServiceCollection(); services.AddSingleton<ICurrentTenant>(current); services.AddSingleton(TimeProvider.System); services.AddHttpContextAccessor(); services.AddDbContext<PlatformDbContext>(x => x.UseInMemoryDatabase(Guid.NewGuid().ToString())); var provider = services.BuildServiceProvider(); var db = provider.GetRequiredService<PlatformDbContext>(); var tenant = new Tenant { Id = tenantId, Name = "Tenant", Slug = $"tenant-{tenantId:N}" }; var site = MakeSite(tenantId, "MAIN"); var other = MakeSite(tenantId, "OTHER"); var user = MakeUser("buyer"); var reviewer = MakeUser("reviewer"); db.AddRange(tenant, site, other, user, reviewer, new TenantMembership { Id = Guid.NewGuid(), TenantId = tenantId, Tenant = tenant, UserId = user.Id, User = user }, new TenantMembership { Id = Guid.NewGuid(), TenantId = tenantId, Tenant = tenant, UserId = reviewer.Id, User = reviewer }); await db.SaveChangesAsync(); var scopes = new SiteScopeAuthorizer(); var audit = new NoAudit(); var inventory = new InventoryService(db, current, scopes, audit, TimeProvider.System); return new(provider, db, new ProcurementService(db, current, scopes, inventory, audit, TimeProvider.System), inventory, tenantId, site, other, user, reviewer); }
        public ClaimsPrincipal User(params (string Permission, Guid Site)[] grants) => Principal(UserEntity, grants);
        public ClaimsPrincipal Reviewer(params (string Permission, Guid Site)[] grants) => Principal(ReviewerUser, grants);
        private static ClaimsPrincipal Principal(PlatformUser actor, (string Permission, Guid Site)[] grants) { IEnumerable<(string Permission, Guid? Site)> values = grants.Length == 0 ? TenantPermissions.All.Select(x => (x, (Guid?)null)) : grants.Select(x => (x.Permission, (Guid?)x.Site)); var claims = new List<Claim> { new("sub", actor.Id.ToString()) }; foreach (var value in values) { claims.Add(new(TenantClaims.Permission, value.Permission)); claims.Add(new(TenantClaims.Grant, new PermissionGrant(value.Permission, value.Site is null ? AccessScopeKind.Tenant : AccessScopeKind.Site, value.Site).ToClaimValue())); } return new(new ClaimsIdentity(claims, "test")); }
        public SupplierInput SupplierInput(string code = "SUP-1") => new(code, code, null, "Contact", "supplier@example.com", "+966500000000", null, null, null, null, "Riyadh", "SA", null, "Net 30", "SAR", null, Guid.Empty);
        public Task<Supplier> Supplier(string code = "SUP-1") => Procurement.CreateSupplier(User(), SupplierInput(code), default);
        public async Task<Warehouse> Warehouse() => await Inventory.CreateWarehouse(User(), new("MAIN", "Main", null, Site.Id, null, Guid.Empty), default);
        public Task<WarehouseStockLocation> Location(Guid warehouse) => Inventory.CreateLocation(User(), new(warehouse, null, "BIN-A", "Bin A", null, Guid.Empty), default);
        public Task<SparePart> Part(string sku = "PART-1") => Inventory.CreatePart(User(), new(sku, sku, null, null, null, null, null, InventoryUnitOfMeasure.Piece, null, 2, 3, null, Guid.Empty), default);
        public RequisitionInput RequisitionInput(Guid warehouse, Guid part, decimal quantity = 10) => new(Site.Id, warehouse, DateOnly.FromDateTime(DateTime.UtcNow), DateOnly.FromDateTime(DateTime.UtcNow.AddDays(7)), ProcurementPriority.Medium, "Replenish stock", null, [new(part, quantity, null, 10, null)], Guid.Empty);
        public async Task<PurchaseRequisition> SubmittedRequisition(decimal quantity = 10) { var warehouse = await Warehouse(); var part = await Part(); var request = await Procurement.CreateRequisition(User(), RequisitionInput(warehouse.Id, part.Id, quantity), default); return await Procurement.SubmitRequisition(User(), request.Id, new(request.Version, null), default); }
        public async Task<PurchaseRequisition> ApprovedRequisition(decimal quantity = 10) { var request = await SubmittedRequisition(quantity); return await Procurement.ReviewRequisition(Reviewer(), request.Id, new(request.Version, true, "Approved"), default); }
        public PurchaseOrderInput OrderInput(PurchaseRequisition request, Guid supplier, decimal quantity, decimal price) { var line = request.Lines.Single(); return new(supplier, request.SiteId, request.TargetWarehouseId, DateOnly.FromDateTime(DateTime.UtcNow), DateOnly.FromDateTime(DateTime.UtcNow.AddDays(14)), "SAR", "Net 30", null, [new(line.Id, line.PartId, quantity, price, null)], Guid.Empty); }
        public async Task<PurchaseOrder> IssuedOrder(decimal quantity, decimal price) { var request = await ApprovedRequisition(quantity); var supplier = await Supplier(); var order = await Procurement.CreatePurchaseOrder(User(), OrderInput(request, supplier.Id, quantity, price), default); return await Procurement.IssuePurchaseOrder(User(), order.Id, new(order.Version, null), default); }
        public PurchaseReceiptInput Receipt(PurchaseOrder order, Guid location, decimal quantity, decimal cost) => new(Guid.NewGuid(), DateOnly.FromDateTime(DateTime.UtcNow), location, null, "DN-1", null, order.Version, [new(order.Lines.Single().Id, quantity, cost)]);
        public static PlatformDbContext CreateDatabase(ICurrentTenant tenant, string name) => new(new DbContextOptionsBuilder<PlatformDbContext>().UseInMemoryDatabase(name).Options, tenant, TimeProvider.System);
        private static Site MakeSite(Guid tenant, string code) => new() { Id = Guid.NewGuid(), TenantId = tenant, Code = code, NameEn = code, TimeZone = "UTC" };
        private static PlatformUser MakeUser(string name) => new() { Id = Guid.NewGuid(), UserName = $"{name}@test.local", Email = $"{name}@test.local", DisplayName = name };
        public async ValueTask DisposeAsync() { await Database.DisposeAsync(); await provider.DisposeAsync(); }
    }
    private sealed class Current(Guid id) : ICurrentTenant { public Guid? Id { get; private set; } = id; public void Initialize(Guid tenantId) => Id = tenantId; }
    private sealed class NoAudit : IAuditWriter { public void Add(string action, string entityType, Guid entityId, object? changes = null) { } }
}
